"""Debugging report generation in JSON and PDF (ReportLab) formats."""

from __future__ import annotations

import io
import json
from datetime import datetime
from typing import Any
from xml.sax.saxutils import escape

from config import APP_NAME, APP_TAGLINE, APP_VERSION

LIMITATIONS = [
    "Static analysis cannot detect every logical error; it only sees code structure.",
    "AI findings and corrections are generated by a language model and may be incorrect; review them.",
    "Complexity estimates from the AI are estimates, not measurements.",
    "Passing tests increases confidence but does not prove the program is correct for all inputs.",
    "LLM-generated tests may encode the model's own misunderstanding of the intended behaviour.",
]


def _recommendations(result: dict[str, Any]) -> list[str]:
    recs: list[str] = []
    status = result.get("repair_status", "")
    issues = result.get("static_issues", []) + result.get("ai_issues", [])
    if any(i.get("severity") == "critical" for i in issues):
        recs.append("Fix the critical syntax/indentation errors first; nothing else can run until then.")
    if status in ("unverified", "no_changes"):
        recs.append("Add independent test cases and run them in the sandbox to verify the correction.")
    if status == "failed_validation":
        recs.append("The AI correction did not pass validation; review the failing tests and fix manually.")
    if status in ("llm_failed", "not_attempted"):
        recs.append("Start Ollama and pull a coding model to enable AI-assisted corrections.")
    metrics = result.get("metrics_after") or result.get("metrics_before") or {}
    if metrics.get("max_complexity", 0) > 10:
        recs.append("Split functions with cyclomatic complexity above 10 into smaller units.")
    if not recs:
        recs.append("Keep the tests with the code and re-run CodeMind AI after future changes.")
    return recs


def build_report_dict(result: dict[str, Any]) -> dict[str, Any]:
    """Assemble the report content from a ``DebugResult.to_dict()`` payload."""
    return {
        "project": APP_NAME, "tagline": APP_TAGLINE, "version": APP_VERSION,
        "analysis_date": datetime.now().isoformat(timespec="seconds"),
        "session_id": result.get("session_id"), "mode": result.get("mode"), "model": result.get("model_name"),
        "expected_behavior": result.get("expected_behavior", ""),
        "original_code": result.get("original_code", ""), "corrected_code": result.get("corrected_code", ""),
        "detected_errors": {"confirmed_static": result.get("static_issues", []),
                            "ai_inferred": result.get("ai_issues", [])},
        "ai_explanation": result.get("explanation", ""), "changes": result.get("changes", []),
        "assumptions": result.get("assumptions", []),
        "quality_comparison": {"before": {"score": result.get("quality_before"),
                                          "metrics": result.get("metrics_before")},
                               "after": {"score": result.get("quality_after"), "metrics": result.get("metrics_after")}},
        "test_results": result.get("test_report"), "repair_status": result.get("repair_status"),
        "repair_attempts": result.get("attempts"), "analysis_duration_seconds": result.get("duration"),
        "notes": result.get("notes", []), "limitations": LIMITATIONS,
        "recommendations": _recommendations(result),
    }


def generate_json_report(result: dict[str, Any]) -> str:
    return json.dumps(build_report_dict(result), indent=2, ensure_ascii=False, default=str)


def generate_pdf_report(result: dict[str, Any]) -> bytes:
    """Render the report as a PDF and return its bytes."""
    from reportlab.lib import colors
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
    from reportlab.lib.units import cm
    from reportlab.platypus import Paragraph, Preformatted, SimpleDocTemplate, Spacer, Table, TableStyle

    data = build_report_dict(result)
    buffer = io.BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=A4, leftMargin=1.8 * cm, rightMargin=1.8 * cm, topMargin=1.5 * cm,
                            bottomMargin=1.5 * cm, title=f"{APP_NAME} Debugging Report")
    styles = getSampleStyleSheet()
    accent = colors.HexColor("#6D5DF6")
    h1 = ParagraphStyle("h1", parent=styles["Title"], textColor=accent)
    h2 = ParagraphStyle("h2", parent=styles["Heading2"], textColor=colors.HexColor("#3B4BC8"), spaceBefore=10)
    body = styles["BodyText"]
    code_style = ParagraphStyle("code", parent=styles["Code"], fontSize=7.5, leading=9.5,
                                backColor=colors.HexColor("#F3F4F8"), borderPadding=4)

    def para(text: str) -> Paragraph:
        return Paragraph(escape(str(text)).replace("\n", "<br/>"), body)

    def code_block(text: str, max_lines: int = 150) -> Preformatted:
        lines = (text or "").splitlines()
        if len(lines) > max_lines:
            lines = lines[:max_lines] + [f"... ({len(lines) - max_lines} more lines)"]
        numbered = "\n".join(f"{i:>3}  {line[:110]}" for i, line in enumerate(lines, 1))
        return Preformatted(numbered or "(empty)", code_style)

    story: list[Any] = [Paragraph(f"{APP_NAME} – Debugging Report", h1), para(APP_TAGLINE), Spacer(1, 6)]
    meta = [["Analysis date", data["analysis_date"]], ["Session ID", str(data["session_id"])],
            ["Mode", str(data["mode"])], ["Model", str(data["model"] or "n/a")],
            ["Repair status", str(data["repair_status"])], ["Repair attempts", str(data["repair_attempts"])],
            ["Analysis time (s)", str(data["analysis_duration_seconds"])]]
    table = Table(meta, colWidths=[4.5 * cm, 12 * cm])
    table.setStyle(TableStyle([("GRID", (0, 0), (-1, -1), 0.3, colors.grey),
                               ("BACKGROUND", (0, 0), (0, -1), colors.HexColor("#ECEBFF")),
                               ("FONTSIZE", (0, 0), (-1, -1), 8.5)]))
    story += [table]

    if data["expected_behavior"]:
        story += [Paragraph("Intended behaviour", h2), para(data["expected_behavior"])]
    story += [Paragraph("Original code", h2), code_block(data["original_code"])]

    story.append(Paragraph("Detected errors", h2))
    rows = [["Line", "Severity", "Category", "Source", "Message"]]
    for label, issues in (("confirmed", data["detected_errors"]["confirmed_static"]),
                          ("AI-inferred", data["detected_errors"]["ai_inferred"])):
        for issue in issues[:60]:
            rows.append([str(issue.get("line") or "-"), issue.get("severity", ""), issue.get("category", ""),
                         f"{issue.get('source', '')} ({label})",
                         Paragraph(escape(str(issue.get("message", "")))[:300], body)])
    if len(rows) == 1:
        rows.append(["-", "-", "-", "-", "No issues detected"])
    issue_table = Table(rows, colWidths=[1.1 * cm, 1.8 * cm, 3.2 * cm, 3.0 * cm, 8.3 * cm], repeatRows=1)
    issue_table.setStyle(TableStyle([("GRID", (0, 0), (-1, -1), 0.3, colors.grey),
                                     ("BACKGROUND", (0, 0), (-1, 0), accent),
                                     ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
                                     ("FONTSIZE", (0, 0), (-1, -1), 7.5), ("VALIGN", (0, 0), (-1, -1), "TOP")]))
    story.append(issue_table)

    if data["corrected_code"] and data["corrected_code"] != data["original_code"]:
        story += [Paragraph("Corrected code", h2), code_block(data["corrected_code"])]
    if data["ai_explanation"] or data["changes"]:
        story.append(Paragraph("AI explanation (AI-generated, review before use)", h2))
        if data["ai_explanation"]:
            story.append(para(data["ai_explanation"]))
        for change in data["changes"]:
            story.append(para(f"• {change}"))

    story.append(Paragraph("Code quality comparison (measured)", h2))
    before = data["quality_comparison"]["before"]
    after = data["quality_comparison"]["after"]
    mb, ma = before.get("metrics") or {}, after.get("metrics") or {}
    q_rows = [["Metric", "Before", "After"],
              ["Quality score (0-100)", str(before.get("score")), str(after.get("score") if after.get("score")
                                                                       is not None else "-")]]
    for key, label in (("loc", "Lines of code"), ("average_complexity", "Avg. cyclomatic complexity"),
                       ("max_complexity", "Max. cyclomatic complexity"),
                       ("maintainability_index", "Maintainability index")):
        q_rows.append([label, str(mb.get(key, "-")), str(ma.get(key, "-")) if ma else "-"])
    q_table = Table(q_rows, colWidths=[7 * cm, 4.5 * cm, 4.5 * cm])
    q_table.setStyle(TableStyle([("GRID", (0, 0), (-1, -1), 0.3, colors.grey),
                                 ("BACKGROUND", (0, 0), (-1, 0), accent), ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
                                 ("FONTSIZE", (0, 0), (-1, -1), 8.5)]))
    story.append(q_table)

    story.append(Paragraph("Test results", h2))
    tests = data["test_results"]
    if tests:
        story.append(para(f"Status: {tests.get('status')} – passed {tests.get('passed')}/{tests.get('total')}. "
                          f"{tests.get('message', '')}"))
    else:
        story.append(para("No tests were executed for this session."))

    if data["notes"]:
        story.append(Paragraph("Pipeline notes", h2))
        for note in data["notes"]:
            story.append(para(f"• {note}"))
    story.append(Paragraph("Analysis limitations", h2))
    for item in data["limitations"]:
        story.append(para(f"• {item}"))
    story.append(Paragraph("Final recommendations", h2))
    for item in data["recommendations"]:
        story.append(para(f"• {item}"))

    doc.build(story)
    return buffer.getvalue()
